def merge_intervals(intervals):
    if not intervals:
        return []
    intervals = sorted(intervals, key=lambda x: x[0])
    merged = [intervals[0]]
    for current in intervals[1:]:
        last = merged[-1]
        if current[0] <= last[1]:
            if current[1] > last[1]:
                merged[-1] = (last[0], current[1])
        else:
            merged.append(current)
    return merged

def schedule_tasks(tasks, max_workers=4):
    queue = sorted(tasks, key=lambda t: t.get("priority", 0), reverse=True)
    assignments = {i: [] for i in range(max_workers)}
    loads = [0] * max_workers
    for task in queue:
        duration = task.get("duration", 1)
        target = 0
        for w in range(max_workers):
            if loads[w] < loads[target]:
                target = w
        if duration <= 0:
            continue
        assignments[target].append(task)
        loads[target] += duration
    return assignments

def compute_discount(total, customer_tier, coupon=None, is_first_order=False):
    rate = 0.0
    if customer_tier == "gold":
        rate = 0.15
    elif customer_tier == "silver":
        rate = 0.10
    elif customer_tier == "bronze":
        rate = 0.05
    if coupon:
        if coupon.startswith("SALE"):
            rate += 0.05
        elif coupon.startswith("VIP"):
            rate += 0.10
    if is_first_order:
        rate += 0.05
    if rate > 0.5:
        rate = 0.5
    return total * (1 - rate)

def validate_password(password, min_length=8, require_digit=True, require_upper=True, require_special=False):
    if len(password) < min_length:
        return False
    has_digit = any(c.isdigit() for c in password)
    has_upper = any(c.isupper() for c in password)
    has_special = any(not c.isalnum() for c in password)
    if require_digit and not has_digit:
        return False
    if require_upper and not has_upper:
        return False
    if require_special and not has_special:
        return False
    return True

def calculate_shipping(weight_kg, distance_km, express=False, fragile=False, country="domestic"):
    base = 5.0
    if weight_kg > 1:
        base += (weight_kg - 1) * 1.5
    if distance_km > 100:
        base += (distance_km - 100) * 0.02
    elif distance_km > 50:
        base += (distance_km - 50) * 0.01
    if express:
        base *= 1.5
    if fragile:
        base += 3.0
    if country == "international":
        base *= 2.0
    elif country == "regional":
        base *= 1.2
    if base > 200:
        base = 200.0
    return round(base, 2)

def build_query_string(params, sort_keys=True, exclude_none=True, encode_spaces=True):
    items = list(params.items())
    if sort_keys:
        items.sort(key=lambda kv: kv[0])
    parts = []
    for key, value in items:
        if value is None:
            if exclude_none:
                continue
            value = ""
        if isinstance(value, bool):
            value = "true" if value else "false"
        elif isinstance(value, (list, tuple)):
            for v in value:
                encoded_v = str(v).replace(" ", "+") if encode_spaces else str(v)
                parts.append(f"{key}={encoded_v}")
            continue
        encoded_value = str(value).replace(" ", "+") if encode_spaces else str(value)
        parts.append(f"{key}={encoded_value}")
    return "&".join(parts)

def normalize_path(path, base=None, strict=False, allow_empty=False):
    if path is None:
        if allow_empty:
            return ""
        raise ValueError("path is required")
    if base:
        if not path.startswith("/"):
            path = base.rstrip("/") + "/" + path
    parts = path.split("/")
    cleaned = []
    for part in parts:
        if part == "" or part == ".":
            continue
        if part == "..":
            if cleaned and strict:
                cleaned.pop()
            elif not strict:
                cleaned.append(part)
        else:
            cleaned.append(part)
    return "/" + "/".join(cleaned)

def classify_shipment_priority(weight_kg, distance_km, value_usd, is_perishable, is_fragile, customer_tier):
    score = 0
    if weight_kg > 20:
        score += 1
    elif weight_kg > 10:
        score += 2
    else:
        score += 3
    if distance_km > 500:
        score -= 2
    elif distance_km > 200:
        score -= 1
    if value_usd > 1000:
        score += 3
    elif value_usd > 100:
        score += 1
    if is_perishable:
        score += 4
    if is_fragile:
        score += 1
    if customer_tier == "gold":
        score += 2
    elif customer_tier == "silver":
        score += 1
    if score >= 8:
        return "urgent"
    elif score >= 5:
        return "high"
    elif score >= 2:
        return "normal"
    else:
        return "low"

def parse_csv_line(line, delimiter=",", quote_char='"', trim_whitespace=False, skip_empty=False):
    fields = []
    current = ""
    in_quotes = False
    i = 0
    while i < len(line):
        ch = line[i]
        if in_quotes:
            if ch == quote_char:
                if i + 1 < len(line) and line[i + 1] == quote_char:
                    current += quote_char
                    i += 1
                else:
                    in_quotes = False
            else:
                current += ch
        else:
            if ch == quote_char:
                in_quotes = True
            elif ch == delimiter:
                if trim_whitespace:
                    current = current.strip()
                if not (skip_empty and current == ""):
                    fields.append(current)
                current = ""
            else:
                current += ch
        i += 1
    if trim_whitespace:
        current = current.strip()
    if not (skip_empty and current == ""):
        fields.append(current)
    return fields

def compute_loan_eligibility(income, credit_score, existing_debt, employment_years, age, has_collateral):
    if age < 18 or age > 70:
        return False
    if credit_score < 500:
        return False
    debt_ratio = existing_debt / income if income > 0 else 1.0
    if debt_ratio > 0.5:
        if not has_collateral:
            return False
        elif credit_score < 650:
            return False
    if employment_years < 1:
        if credit_score < 700:
            return False
    elif employment_years < 3:
        if credit_score < 600:
            return False
    if credit_score >= 750:
        return True
    elif credit_score >= 650:
        return debt_ratio <= 0.4
    else:
        return debt_ratio <= 0.2 and has_collateral

def grade_exam(score, attendance_pct, has_late_penalty, extra_credit, is_makeup_exam, has_disability_accommodation):
    adjusted = score
    if has_late_penalty:
        if has_disability_accommodation:
            adjusted -= 2
        else:
            adjusted -= 5
    adjusted += extra_credit
    if attendance_pct < 50:
        if has_disability_accommodation:
            adjusted -= 5
        else:
            adjusted -= 10
    elif attendance_pct < 75:
        adjusted -= 5
    if is_makeup_exam:
        adjusted = min(adjusted, 80)
    if adjusted >= 90:
        grade = "A"
    elif adjusted >= 80:
        grade = "B"
    elif adjusted >= 70:
        grade = "C"
    elif adjusted >= 60:
        grade = "D"
    else:
        grade = "F"
    if grade == "F" and attendance_pct >= 90:
        grade = "D"
    return grade

def validate_form_submission(fields, required_fields, max_lengths, custom_validators):
    errors = []
    for field in required_fields:
        if field not in fields or not fields[field]:
            errors.append(f"{field} is required")
    for field, value in fields.items():
        if field in max_lengths:
            if value and len(value) > max_lengths[field]:
                errors.append(f"{field} exceeds max length")
        if field in custom_validators:
            validator = custom_validators[field]
            if value:
                if not validator(value):
                    errors.append(f"{field} failed validation")
    if "email" in fields and fields["email"]:
        if "@" not in fields["email"]:
            errors.append("invalid email")
        elif fields["email"].count("@") > 1:
            errors.append("invalid email")
    return errors

def compute_tax_bracket(income, filing_status, deductions, dependents, is_senior):
    taxable = income - deductions
    if dependents > 0:
        taxable -= dependents * 2000
    if is_senior:
        taxable -= 1500
    if taxable < 0:
        taxable = 0
    if filing_status == "single":
        if taxable <= 10000:
            rate = 0.10
        elif taxable <= 40000:
            rate = 0.15
        elif taxable <= 90000:
            rate = 0.25
        else:
            rate = 0.35
    elif filing_status == "married":
        if taxable <= 20000:
            rate = 0.10
        elif taxable <= 80000:
            rate = 0.15
        else:
            rate = 0.25
    else:
        rate = 0.20
    tax = taxable * rate
    if is_senior and tax > 0:
        tax *= 0.95
    return round(tax, 2)

def detect_anomaly(readings, baseline, tolerance_pct, min_consecutive, allow_negative_spike, smoothing=False, reset_on_recovery=True):
    anomalies = []
    consecutive = 0
    prev_value = None
    for i, value in enumerate(readings):
        if smoothing and prev_value is not None:
            value = (value + prev_value) / 2
        deviation = (value - baseline) / baseline if baseline != 0 else 0
        is_high = deviation > tolerance_pct
        is_low = deviation < -tolerance_pct and not allow_negative_spike
        if is_high or is_low:
            consecutive += 1
            if consecutive >= min_consecutive:
                if is_high:
                    anomalies.append((i, "high"))
                elif is_low:
                    anomalies.append((i, "low"))
        else:
            if reset_on_recovery:
                consecutive = 0
            elif consecutive > 0:
                consecutive -= 1
        prev_value = value
    return anomalies

def assign_seat(passenger, available_seats, preferences, is_vip, group_size):
    if is_vip:
        for seat in available_seats:
            if seat.get("class") == "first":
                return seat
    if group_size > 1:
        for seat in available_seats:
            if seat.get("adjacent_free", 0) >= group_size - 1:
                return seat
    if preferences.get("window"):
        for seat in available_seats:
            if seat.get("type") == "window":
                return seat
    elif preferences.get("aisle"):
        for seat in available_seats:
            if seat.get("type") == "aisle":
                return seat
    return available_seats[0] if available_seats else None

def getitem_block(self, slicer, new_mgr_locs=None):
        """
        Perform __getitem__-like, return result as block.

        As of now, only supports slices that preserve dimensionality.
        """
        if new_mgr_locs is None:
            if isinstance(slicer, tuple):
                axis0_slicer = slicer[0]
            else:
                axis0_slicer = slicer
            new_mgr_locs = self.mgr_locs[axis0_slicer]

        new_values = self._slice(slicer)

        if self._validate_ndim and new_values.ndim != self.ndim:
            raise ValueError("Only same dim slicing is allowed")

        return self.make_block_same_class(new_values, new_mgr_locs)

def apply_axis_properties(self, axis, rot=None, fontsize=None):
        """ Tick creation within matplotlib is reasonably expensive and is
            internally deferred until accessed as Ticks are created/destroyed
            multiple times per draw. It's therefore beneficial for us to avoid
            accessing unless we will act on the Tick.
        """

        if rot is not None or fontsize is not None:
            # rot=0 is a valid setting, hence the explicit None check
            labels = axis.get_majorticklabels() + axis.get_minorticklabels()
            for label in labels:
                if rot is not None:
                    label.set_rotation(rot)
                if fontsize is not None:
                    label.set_fontsize(fontsize)

def construction_error(tot_items, block_shape, axes, e=None):
    """ raise a helpful message about our construction """
    passed = tuple(map(int, [tot_items] + list(block_shape)))
    # Correcting the user facing error message during dataframe construction
    if len(passed) <= 2:
        passed = passed[::-1]

    implied = tuple(len(ax) for ax in axes)
    # Correcting the user facing error message during dataframe construction
    if len(implied) <= 2:
        implied = implied[::-1]

    if passed == implied and e is not None:
        raise e
    if block_shape[0] == 0:
        raise ValueError("Empty data passed with indices specified.")
    raise ValueError("Shape of passed values is {0}, indices imply {1}".format(
        passed, implied))

def rehydrate_skeleton_class(skeleton_class, class_dict):
    """Put attributes from `class_dict` back on `skeleton_class`.

    See CloudPickler.save_dynamic_class for more info.
    """
    registry = None
    for attrname, attr in class_dict.items():
        if attrname == "_abc_impl":
            registry = attr
        else:
            setattr(skeleton_class, attrname, attr)
    if registry is not None:
        for subclass in registry:
            skeleton_class.register(subclass)

    return skeleton_class

def extend_blocks(result, blocks=None):
    """ return a new extended blocks, givin the result """
    from pandas.core.internals import BlockManager
    if blocks is None:
        blocks = []
    if isinstance(result, list):
        for r in result:
            if isinstance(r, list):
                blocks.extend(r)
            else:
                blocks.append(r)
    elif isinstance(result, BlockManager):
        blocks.extend(result.blocks)
    else:
        blocks.append(result)
    return blocks

def preprocess_sgm(line, is_sgm):
  """Preprocessing to strip tags in SGM files."""
  if not is_sgm:
    return line
  # In SGM files, remove <srcset ...>, <p>, <doc ...> lines.
  if line.startswith("<srcset") or line.startswith("</srcset"):
    return ""
  if line.startswith("<doc") or line.startswith("</doc"):
    return ""
  if line.startswith("<p>") or line.startswith("</p>"):
    return ""
  # Strip <seg> tags.
  line = line.strip()
  if line.startswith("<seg") and line.endswith("</seg>"):
    i = line.index(">")
    return line[i + 1:-6]

def add_to_capabilities(self, capabilities):
        """
        Adds proxy information as capability in specified capabilities.

        :Args:
         - capabilities: The capabilities to which proxy will be added.
        """
        proxy_caps = {}
        proxy_caps['proxyType'] = self.proxyType['string']
        if self.autodetect:
            proxy_caps['autodetect'] = self.autodetect
        if self.ftpProxy:
            proxy_caps['ftpProxy'] = self.ftpProxy
        if self.httpProxy:
            proxy_caps['httpProxy'] = self.httpProxy
        if self.proxyAutoconfigUrl:
            proxy_caps['proxyAutoconfigUrl'] = self.proxyAutoconfigUrl
        if self.sslProxy:
            proxy_caps['sslProxy'] = self.sslProxy
        if self.noProxy:
            proxy_caps['noProxy'] = self.noProxy
        if self.socksProxy:
            proxy_caps['socksProxy'] = self.socksProxy
        if self.socksUsername:
            proxy_caps['socksUsername'] = self.socksUsername
        if self.socksPassword:
            proxy_caps['socksPassword'] = self.socksPassword
        capabilities['proxy'] = proxy_caps

def factorial(n, mod=None):
    """Calculates factorial iteratively.
    If mod is not None, then return (n! % mod)
    Time Complexity - O(n)"""
    if not (isinstance(n, int) and n >= 0):
        raise ValueError("'n' must be a non-negative integer.")
    if mod is not None and not (isinstance(mod, int) and mod > 0):
        raise ValueError("'mod' must be a positive integer")
    result = 1
    if n == 0:
        return 1
    for i in range(2, n+1):
        result *= i
        if mod:
            result %= mod
    return result

def three_sum(array):
    """
    :param array: List[int]
    :return: Set[ Tuple[int, int, int] ]
    """
    res = set()
    array.sort()
    for i in range(len(array) - 2):
        if i > 0 and array[i] == array[i - 1]:
            continue
        l, r = i + 1, len(array) - 1
        while l < r:
            s = array[i] + array[l] + array[r]
            if s > 0:
                r -= 1
            elif s < 0:
                l += 1
            else:
                # found three sum
                res.add((array[i], array[l], array[r]))

                # remove duplicates
                while l < r and array[l] == array[l + 1]:
                    l += 1

                while l < r and array[r] == array[r - 1]:
                    r -= 1

                l += 1
                r -= 1
    return res

def process_nested_expression(self, nested_expression) -> str:
        """
        ``nested_expression`` is the result of parsing a logical form in Lisp format.
        We process it recursively and return a string in the format that NLTK's ``LogicParser``
        would understand.
        """
        expression_is_list = isinstance(nested_expression, list)
        expression_size = len(nested_expression)
        if expression_is_list and expression_size == 1 and isinstance(nested_expression[0], list):
            return self.process_nested_expression(nested_expression[0])
        elements_are_leaves = [isinstance(element, str) for element in nested_expression]
        if all(elements_are_leaves):
            mapped_names = [self._map_name(name) for name in nested_expression]
        else:
            mapped_names = []
            for element, is_leaf in zip(nested_expression, elements_are_leaves):
                if is_leaf:
                    mapped_names.append(self._map_name(element))
                else:
                    mapped_names.append(self.process_nested_expression(element))
        if mapped_names[0] == "\\":
            # This means the predicate is lambda. NLTK wants the variable name to not be within parantheses.
            # Adding parentheses after the variable.
            arguments = [mapped_names[1]] + [f"({name})" for name in mapped_names[2:]]
        else:
            arguments = [f"({name})" for name in mapped_names[1:]]
        return f'({mapped_names[0]} {" ".join(arguments)})'
